<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class DocumentIntegrationService{
public function create($user,$periodId,string $module,string $entityType,int $entityId,string $type,string $title,array $snapshot=[],array $options=[]):int{
$existing=DB::table('document_links')->where(['module'=>$module,'entity_type'=>$entityType,'entity_id'=>$entityId,'relation'=>$options['relation']??'source'])->value('official_document_id');if($existing)return (int)$existing;
return DB::transaction(function()use($user,$periodId,$module,$entityType,$entityId,$type,$title,$snapshot,$options){$seq=(DB::table('official_documents')->max('id')??0)+1;$num=sprintf('DOC-%s-%06d',date('Y'),$seq);$id=DB::table('official_documents')->insertGetId(['number'=>$num,'type'=>$type,'academic_period_id'=>$periodId,'direction'=>$options['direction']??'internal','title'=>$title,'document_date'=>$options['document_date']??date('Y-m-d'),'correspondent'=>$options['correspondent']??null,'confidentiality'=>$options['confidentiality']??'internal','due_on'=>$options['due_on']??null,'summary'=>$options['summary']??null,'source_module'=>$module,'source_type'=>$entityType,'source_id'=>$entityId,'status'=>'draft','current_version'=>1,'created_by'=>$user->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('document_versions')->insert(['official_document_id'=>$id,'version'=>1,'title'=>$title,'body'=>$options['body']??null,'snapshot_json'=>json_encode($snapshot,JSON_UNESCAPED_UNICODE),'created_by'=>$user->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('document_links')->insert(['official_document_id'=>$id,'module'=>$module,'entity_type'=>$entityType,'entity_id'=>$entityId,'relation'=>$options['relation']??'source','created_at'=>now(),'updated_at'=>now()]);DB::table('official_document_events')->insert(['official_document_id'=>$id,'user_id'=>$user->id,'event'=>'created_from_module','details'=>$module.':'.$entityType.'#'.$entityId,'created_at'=>now(),'updated_at'=>now()]);return $id;});}
public function linked(string $module,string $type,int $id){return DB::table('document_links as l')->join('official_documents as d','d.id','=','l.official_document_id')->where(['l.module'=>$module,'l.entity_type'=>$type,'l.entity_id'=>$id])->select('d.*','l.relation')->get();}
}